<?php require_once __DIR__.'/includes/content-v2.php';foreach(['brand'=>'BRANDS WE HAVE WORKED WITH','testimonial'=>'CLIENT STORIES'] as $kind=>$heading):$items=acp_content($kind);if(!$items)continue;?><section class="acp-v2-marquee"><div class="wrap"><span class="kicker"><?=acp_h($heading)?></span></div><div class="acp-v2-track"><?php for($repeat=0;$repeat<2;$repeat++):foreach($items as $item):?><article class="acp-v2-pill"><strong><?=acp_h($item['title'])?></strong><p><?=acp_h($item['subtitle'])?></p></article><?php endforeach;endfor;?></div></section><?php endforeach;?>